from taf.gnb.oam.coam.cu.services.internal.emservice.http_client import EMServicev1HttpClient
from taf.gnb.oam.coam.cu.utilities.poll_status import poll_status
from taf.gnb.oam.coam.cu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.cu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.cu.services.internal.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.cu.services.licensed.sec.sec_licensed_v1 import SECLicensedv1


@auto_token_refresh()
class EMServicev1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        self.local_client = EMServicev1HttpClient(base_url=con_details.base_url,
                                                  connection_alias=con_details.alias)

    def search_parameters_of_current_plan(self, parameter_name, **kwargs):
        return self.local_client.search_parameters_of_current_plan(parameter_name=parameter_name, **kwargs)

    def get_staged_plans(self):
        return self.local_client.get_staged_plans()

    def plan_validation(self, plan_id, wait_for_completion=False, timeout=30):
        operation = self.local_client.plan_validation(plan_id=plan_id)

        if wait_for_completion:
            method_name = "get_operation_state_of_validating_plan"

            return poll_status(instance=self.local_client, method_name=method_name,
                               operation_id=operation["actionId"], timeout=timeout, plan_id=plan_id)

        return operation

    def get_operation_state_of_validating_plan(self, plan_id, operation_id, timeout=30):
        return self.local_client.get_operation_state_of_validating_plan(plan_id=plan_id, operation_id=operation_id,
                                                                        timeout=timeout)

    def download_staged_plan_file(self, plan_id, include_auto_config_data=False):
        return self.local_client.download_staged_plan_file(plan_id=plan_id,
                                                           include_auto_config_data=include_auto_config_data)

    def get_validation_result_of_staged_plan(self, plan_id, validation_id, error_type):
        return self.local_client.get_validation_result_of_staged_plan(plan_id=plan_id, validation_id=validation_id,
                                                                      error_type=error_type)

    def fix_plan_validation_errors(self, plan_id, add_missing_objects, timeout=30):
        return self.local_client.fix_plan_validation_errors(plan_id=plan_id, add_missing_objects=add_missing_objects,
                                                            timeout=timeout)

    def get_action_state_of_fix_plan(self, plan_id, action_id):
        return self.local_client.get_action_state_of_fix_plan(plan_id=plan_id, action_id=action_id)
